import { createECDH } from 'node:crypto';
import { curveOrder, inverse, mod, randomScalar, seal, sha256, toBytes, toInteger } from '../core.mjs';

// Nonces are generated by a stateful affine generator and signatures use low-s
// normalization. No nonce is reused. Artifacts are shuffled audit events.
export function affineArchive(code, receipt, random) {
  const d = randomScalar(random), multiplier = randomScalar(random), increment = randomScalar(random);
  let nonce = randomScalar(random);
  const key = createECDH('secp256k1'); key.setPrivateKey(toBytes(d));
  const signatures = [];
  for (let i = 0; i < 12; i++) {
    nonce = mod(nonce * multiplier + increment, curveOrder) || 1n;
    const message = JSON.stringify({ epoch: 1726311600, seq: 4096 + i, account: random(8).toString('hex'), operation: i % 3 === 0 ? 'reserve' : i % 3 === 1 ? 'settle' : 'checkpoint', amount: String(1000000 + random(3).readUIntBE(0, 3)), previous: i ? sha256(signatures.at(-1).message).toString('hex') : '0'.repeat(64) });
    const point = createECDH('secp256k1'); point.setPrivateKey(toBytes(nonce));
    const r = mod(toInteger(point.getPublicKey().subarray(1, 33)), curveOrder);
    const z = toInteger(sha256(Buffer.from(message)));
    let s = mod(inverse(nonce, curveOrder) * (z + r * d), curveOrder);
    if (s > curveOrder / 2n) s = curveOrder - s;
    signatures.push({ message, r: toBytes(r).toString('hex'), s: toBytes(s).toString('hex') });
  }
  for (let i = signatures.length - 1; i; i--) {
    const j = random(2).readUInt16BE(0) % (i + 1);
    [signatures[i], signatures[j]] = [signatures[j], signatures[i]];
  }
  return {
    'ledger.json': JSON.stringify({ format: 'ECDSA/secp256k1', hash: 'SHA-256(UTF-8 message)', scalarEncoding: 'unsigned big-endian, 32 bytes', publicKey: key.getPublicKey('hex', 'uncompressed'), signatures }, null, 2),
    'sealed-letter.json': JSON.stringify({ ...seal({ code, receipt }, toBytes(d), 'afterglow/case-08', random), recipient: sha256(key.getPublicKey()).toString('hex') }, null, 2),
    'signer-build.json': JSON.stringify({ target: 'secp256k1', provider: 'archive-hsm', firmware: '3.11.9', flags: ['LOW_S', 'MONOTONIC_AUDIT'], registers: [{ name: 'R0', width: 256 }, { name: 'R1', width: 256 }, { name: 'R2', width: 256 }], microcode: ['MUL R0,R1', 'ADD R0,R2', 'REDUCE R0,N', 'SIGN R0', 'INC SEQ'] }, null, 2),
  };
}
